pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address recipient = address(0x123);
        // First call: reference succeeds, bug reverts because claimedBonus[recipient] is false
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        // Second call: reference sets claimedBonus[recipient] to true again (redundant but reverts because already true? Actually reference require(!claimedBonus[recipient]) fails on second call, so it reverts)
        // Let's use a fresh recipient instead to demonstrate divergence clearly
        address recipient2 = address(0x456);
        // First call to getFirstWithdrawalBonus by fresh recipient: reference succeeds, bug reverts
        (bool okRef, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient2));
        // Reference succeeded (okRef true) because !claimedBonus[recipient2] holds
        // Bug reverted (okRef false) because require(claimedBonus[recipient2]) fails
        // Assert: in reference, okRef is true; in bug, okRef is false
        assertTrue(okRef == true);
    }
}

