pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 0);

        // First call by alice: reference succeeds, bug reverts
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", alice));

        // Second call by alice: reference reverts (claimedBonus true), but bug now succeeds (claimedBonus true -> require passes)
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", alice));

        // Reference: first call true, second false -> ok1 && !ok2
        // Bug: first false, second true -> !ok1 && ok2
        assertTrue(ok1 && !ok2);
    }
}

