pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address recipient = address(0xABCD);
        vm.deal(address(this), 1 ether);
        vm.deal(recipient, 0 ether);

        // Call getFirstWithdrawalBonus
        vm.prank(address(this));
        c.getFirstWithdrawalBonus(recipient);

        // Check the contract's eth balance after the call
        // Reference contract: sends 100 wei → balance = 0 (since no eth was sent to contract)
        // Buggy contract: revert inside withdrawReward due to reentrancy lock
        // Actually, the buggy version sets claimedBonus before withdrawReward, which is fine,
        // but the reentrancy modifier _nonReentrant prevents reentrancy; however no reentrancy here
        // The actual difference: in reference, rewardsForA is set to 0 after sending, so no more reward;
        // in buggy, claimedBonus is set first, so require(!claimedBonus) will fail on a second call,
        // but that's not the point. Let's think more carefully:
        // The change moves claimedBonus = true before withdrawReward. 
        // withdrawReward uses _nonReentrant, which will set _locked = true.
        // After withdrawReward returns, _locked = false.
        // No reentrancy happens. So both will send 100 wei.
        // The difference P != M in the statement "P.getFirstWithdrawalBonus() != M.getFirstWithdrawalBonus()" 
        // is about the getter? But that makes no sense; getFirstWithdrawalBonus is a function, not a getter.
        // I think the intended difference is about the contract's balance after the call:
        // In reference: withdrawReward sets rewardsForA[recipient] = 0 after reading 100 and sends 100 wei.
        // The contract must have at least 100 wei to send; we need to fund it.
        // In bug: same sending happens, so balance after should be the same.
        // Wait, maybe the bug is that claiming bonus before withdrawReward allows reentry because
        // claimedBonus is set, but then withdrawReward can be called again? No, _nonReentrant prevents that.
        // Let's read the description: "after a call to getFirstWithdrawalBonus(...) completes, the value of
        // state variable getFirstWithdrawalBonus differs" — that's a typo? Actually the state variable
        // is not named getFirstWithdrawalBonus, that's the function. 
        // The description might be wrong. The real difference is:
        // Reference: rewardsForA[recipient] is read, then set to 0, then 100 sent, then claimedBonus set.
        // Bug: rewardsForA[recipient] read, then claimedBonus set, then withdrawReward called which sets
        // rewardsForA to 0 and sends 100. But since claimedBonus is set first, a second call would fail.
        // However, the first call still succeeds and sends 100. Where is the divergence?
        // The only observable difference I can think of: after the call, `claimedBonus(recipient)` returns
        // true in both cases. `rewardsForA(recipient)` returns 0 in both. `userBalances` is not touched.
        // Balance of contract should be the same. 
        // However, in the bug version, if withdrawReward were to call back into getFirstWithdrawalBonus
        // via a malicious recipient, the _nonReentrant would lock, but that's not happening here.
        // I think the intended bug is a reentrancy scenario: the recipient's fallback could call
        // getFirstWithdrawalBonus again before claimedBonus is set in the reference, allowing double claim.
        // In the bug, claimedBonus is set first, preventing that. But the description says reference correct,
        // buggy breaks. So maybe the reference is meant to be vulnerable? No, the reference is the correct one.
        // I'm confused. Let me just create a concrete scenario where the recipient is a contract that
        // reenters in its fallback. In reference, claimedBonus is set after withdrawReward, so reentrant
        // call goes through? Actually, withdrawReward sets rewards to 0 before external call, so reentrant
        // call would see 0 and send 0. Not double claim. 
        // So maybe the difference is in the contract's balance: reference sends 100, bug sends 0 because
        // the reentrancy lock causes revert? Let's design: recipient is a malicious contract that in its
        // fallback calls getFirstWithdrawalBonus again. 
        // In reference: first getFirstWithdrawalBonus: require(!claimedBonus) passes, rewardsForA += 100,
        // then withdrawReward: _nonReentrant sets _locked, reads rewardsForA = 100, sets it to 0, then
        // makes external call. Fallback calls getFirstWithdrawalBonus again: require(!claimedBonus) passes
        // (still false), rewardsForA += 100 (now 100 again since set to 0), then withdrawReward: _nonReentrant
        // would revert because _locked is already true! So the reentrant call reverts at the modifier.
        // The external call from first withdrawReward continues, sends 100, then _locked = false, then
        // claimedBonus = true. 
        // In bug: first getFirstWithdrawalBonus sets claimedBonus = true before calling withdrawReward.
        // Then withdrawReward: _nonReentrant sets _locked, reads rewardsForA = 100, sets to 0, external call.
        // Fallback tries getFirstWithdrawalBonus again: require(!claimedBonus) FAILS because already true,
        // so reverts. First call completes, sends 100, _locked = false. 
        // So both end with same balance? The reentrant call reverts in both. No difference in final state.
        // I'm stuck. The problem statement says the difference is: after call, value of state variable 
        // `getFirstWithdrawalBonus` differs. That's not a state variable. Maybe the difference is that
        // in reference, the getter `claimedBonus(recipient)` returns false after the call because the
        // reentrant call doesn't set it? No, it sets it at the end. 
        // I'll try this: use a plain EOA recipient. Both should send 100 wei. To make them differ, we need
        // the contract to not have enough balance. Fund it with 50 wei. In reference: withdrawReward tries 
        // to send 100 but requires success, so it reverts because insufficient balance. In bug: same, reverts.
        // No difference. 
        // The only way I see a difference: if the recipient is a contract that in its fallback reverts,
        // then both revert. If the recipient is a contract that in its fallback does nothing, both succeed.
        // The bug moves claimedBonus before withdrawReward, but that doesn't affect the outcome for a single
        // call with an EOA. 
        // I think the key is that in the reference, if withdrawReward reverts (e.g., insufficient balance),
        // then claimedBonus is NOT set because the assignment occurs after withdrawReward. In the bug,
        // claimedBonus IS set before withdrawReward, so even if withdrawReward reverts, claimedBonus remains
        // true, meaning the user cannot retry. So the difference is: after a failed withdrawReward call
        // (due to insufficient balance), claimedBonus is false in reference (user can retry) and true in bug
        // (user cannot). So let's set up the contract with insufficient balance to cause a revert.
        vm.deal(address(c), 50); // contract has only 50 wei, cannot pay 100
        // Call getFirstWithdrawalBonus; it will revert at require(success) in withdrawReward
        // In reference: claimedBonus stays false; in bug: claimedBonus becomes true before revert.
        // We'll capture the revert status:
        bool ok;
        vm.prank(address(this));
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // Now check claimedBonus[recipient]
        bool claimedAfterCall = c.claimedBonus(recipient);
        // Reference: claimedAfterCall should be false (since withdrawReward reverted before assignment)
        // Bug: claimedAfterCall should be true (assignment before withdrawReward)
        // So we assert that claimedAfterCall is false (as in reference)
        assertTrue(!claimedAfterCall);
    }
}

