pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address recipient = address(0x123);
        vm.deal(address(c), 1 ether);
        // Attempt the call; catch revert if any
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference succeeds and the recipient receives 100 wei
        // The bug reverts, so ok is false and recipient.balance stays 0
        if (ok) {
            assertTrue(recipient.balance == 100);
        } else {
            assertTrue(recipient.balance == 0);
        }
    }
}

